Subject: [PATCH] applets/kicker: keep the favorites ordering when cloning a
 panel

Kicker-based launchers save their favorites ordering under their applet
id, so a cloned or swapped launcher had none and guessed it from another
instance. Pass the old applet id to the new one so it can import it.

BUG: 514303
---
 applets/kicker/kastatsfavoritesmodel.cpp | 29 ++++++++++++++++++++++++
 applets/kicker/kastatsfavoritesmodel.h   |  1 +
 shell/alternativeshelper.cpp             | 14 ++++++++++--
 shell/shellcorona.cpp                    | 10 +++++++-
 4 files changed, 51 insertions(+), 3 deletions(-)

diff --git a/applets/kicker/kastatsfavoritesmodel.cpp b/applets/kicker/kastatsfavoritesmodel.cpp
index 224337a54c..b446db6244 100644
--- a/applets/kicker/kastatsfavoritesmodel.cpp
+++ b/applets/kicker/kastatsfavoritesmodel.cpp
@@ -496,6 +496,26 @@ public:
         cfg->sync();
     }

+    static void importOrderingFromApplet(uint oldInstanceId, uint newInstanceId, const QString &pluginName)
+    {
+        qCDebug(KICKER_DEBUG) << "Importing ordering from applet id" << oldInstanceId << "to applet id" << newInstanceId;
+        const auto cfg = KSharedConfig::openConfig(QStringLiteral("kactivitymanagerd-statsrc"));
+        const auto allGroups = cfg->groupList();
+        const QString oldGroupNamePart = QStringLiteral(".favorites.instance-%1-").arg(oldInstanceId);
+        const QString newGroupNamePrefix = u"Favorites-" + pluginName + QStringLiteral(".favorites.instance-%1-").arg(newInstanceId);
+        for (const QString &groupName : allGroups) {
+            // the group names look like "Favorites-org.kde.plasma.kicker.favorites.instance-58-1bd5bb42-187c-4c77-a746-c9644c5da866"
+            const int index = groupName.indexOf(oldGroupNamePart);
+            if (!groupName.startsWith(u"Favorites-") || index == -1) {
+                continue;
+            }
+            const QString activity = groupName.mid(index + oldGroupNamePart.length());
+            const auto ordering = KConfigGroup(cfg, groupName).readEntry("ordering", QStringList());
+            KConfigGroup(cfg, newGroupNamePrefix + activity).writeEntry("ordering", ordering);
+        }
+        cfg->sync();
+    }
