+void KAStatsFavoritesModel::importOrderingFromApplet(uint oldInstanceId, uint newInstanceId, const QString &pluginName)
+{
+    Private::importOrderingFromApplet(oldInstanceId, newInstanceId, pluginName);
+    if (d && m_activities->serviceStatus() == KActivities::Consumer::Running) {
